/**
 * 문서를 열 때 나눠 받는 조각(dynamic import — 첫 화면 JS에서 문서가 없을 때 쓰지 않는 코드를 뺀다).
 *
 * - 3D 뷰어 코어(opencad-viewer3d 입구 → viewer·renderer·셰이더·고르기): 시작 화면(파일 열기·최근 문서·예제·언어 메뉴)은 코어 없이 그린다.
 *   앱은 코어의 작은 모듈(camera 뷰 이름·표준 뷰 키 표·카메라 계산, pointer 터치 거리, theme 테마 색,
 *   section 단면 수 한도)만 바로 가져오고, 코어 입구와 뷰 큐브 모듈(viewcube — 54차)은 여기서만 가져온다.
 * - 측정 도구(measure.ts 줄자·각도기·안내 두기·고르기, snap.ts 추정, 코어 inference 교차점·추론 잠금): 키·안내 글은 measurehints.ts에 남긴다.
 * - 파일을 열기 시작하면 워커 해석과 함께 둘 다 받기 시작한다(app.ts openBuffer). 측정 도구는 받는 대로 만들고, 그 전에 켜면 받은 뒤에 켠다.
 *   오프라인 앱은 서비스 워커가 이 조각들도 미리 담아 둔다.
 * - 받지 못하면(오프라인에서 새 판 등) 약속을 비워 다음 부름에서 다시 받는다.
 * - 큰 모형 놓기·그래픽 문맥 잃음과 되찾음(release.ts — 27차, 29차에 되찾기를 바꿈): 파일을 열기 시작할 때 함께 받는다. 받지 못하면 놓지 않고 안내만 없다.
 */
import { localizeCubeFaces } from './i18n';

/**
 * 코어 입구에서 앱이 쓰는 것(Viewer3d 하나 — 60차). 입구 모듈 전체(이름공간)를 넘기면 번들러가 입구가 내보내는 모든 것을 코어 조각에 남기고
 * 첫 화면 조각에 있는 작은 모듈의 함수(코어 0.54.0 viewKeyOf 등)까지 조각 사이로 내보낸다. import().then의 나눈 이름만 남긴다(rollup 동적 가져오기 나무 흔들기)
 */
type Core = Pick<typeof import('opencad-viewer3d'), 'Viewer3d'>;
type Measure = typeof import('./measure');
type Release = typeof import('./release');
type Sections = typeof import('./sections');
type KeyPicking = typeof import('./keypick');
type PickListing = typeof import('./picklist');
type SunLight = typeof import('./sun');
type Annotating = typeof import('./annotations');

/**
 * 파일 단면 → 코어 평면 계산(sections.ts — 55차: 구간 단면을 더하며 첫 화면 조각에서 뺐다). 코어 입구와 함께 받아 두므로
 * 뷰어가 있으면 늘 있다(단면은 뷰어가 있어야 쓴다). 받기 전에는 null
 */
export let fileSections: Sections | null = null;
/** 3D 보기 키보드 고르기(keypick.ts — 56차, 가상 커서·겹친 것 고르기 돌리기). fileSections처럼 코어 입구와 함께 받는다(받기 전에는 null) */
export let keyPicking: KeyPicking | null = null;
/** 3D 보기 겹친 것 고르기 목록(picklist.ts — 57차, 오른쪽 단추·길게 누르기·Shift+F10). keyPicking처럼 코어 입구와 함께 받는다(받기 전에는 null) */
export let pickListing: PickListing | null = null;
/**
 * 글·치수 라벨(annotations.ts — 57차: 겹친 것 목록을 더하며 첫 화면 조각에서 뺐다). 라벨은 뷰어 덧그림 위에 그리므로 코어 입구와 함께 받는다
 * (뷰어를 만들 때 라벨 그리기를 만든다 — 받기 전에는 null)
 */
export let annotating: Annotating | null = null;
/**
 * 해 조명·안개 계산(sun.ts — 56차: 키보드 고르기를 더하며 첫 화면 조각에서 뺐다). 조명은 뷰어가 있어야 걸므로 코어 입구와 함께 받는다(받기 전에는 null —
 * 상태 보내기의 해 자리도 null)
 */
export let sunLight: SunLight | null = null;

/** import()를 한 번만 부르는 받기: 받는 동안·받은 뒤에는 같은 약속을 주고, 받지 못하면 비워 다음 부름에서 다시 받는다 */
export function onceImport<T>(load: () => Promise<T>): () => Promise<T> {
  let pending: Promise<T> | null = null;
  return () => {
    if (!pending) {
      const p = load();
      pending = p;
      p.catch(() => {
        if (pending === p) pending = null;
      });
    }
    return pending;
  };
}

/**
 * 코어 입구 모듈(한 번만 받는다). 뷰 큐브 모듈(viewcube — 면 글 CUBE_FACES)도 함께 받아 지금 언어로 옮긴 뒤 준다
 * (54차: 첫 화면이 바로 가져오던 것을 뺐다 — 코어 0.44.0 손가락 큐브로 커진 모듈이 첫 화면 조각에 실렸다. 뷰어를 만들기 전에 옮기므로 큐브는 처음부터 그 언어로 그린다)
 */
export const loadViewerCore: () => Promise<Core> = onceImport(() =>
  Promise.all([
    import('opencad-viewer3d').then(({ Viewer3d }) => ({ Viewer3d })),
    import('opencad-viewer3d/viewcube'),
    import('./sections'),
    import('./keypick'),
    import('./sun'),
    import('./picklist'),
    import('./annotations'),
  ]).then(([core, cube, sections, keys, sun, list, notes]) => {
    localizeCubeFaces(cube.CUBE_FACES);
    fileSections = sections;
    keyPicking = keys;
    sunLight = sun;
    pickListing = list;
    annotating = notes;
    return core;
  }),
);

/** 측정 도구 조각(한 번만 받는다) */
export const loadMeasure: () => Promise<Measure> = onceImport(() => import('./measure'));

/** 큰 모형 놓기·문맥 복구 조각(한 번만 받는다) */
export const loadRelease: () => Promise<Release> = onceImport(() => import('./release'));

/** 나눠 받는 조각을 받지 못한 오류인지(브라우저마다 글이 다르다: Chrome·Edge, Firefox, Safari) */
export function isChunkLoadError(e: unknown): boolean {
  const msg = e instanceof Error ? e.message : String(e ?? '');
  return /dynamically imported module|Importing a module script failed|error loading dynamically imported module|Unable to preload/i.test(msg);
}

/**
 * 조각 받기 실패 안내: 연결이 끊겼으면 연결된 뒤 다시, 아니면 앱의 새 버전이 나와 예전 조각이 없을 수 있으니 새로 고친 뒤
 * (열어 둔 파일은 새 버전 알림처럼 최근 문서에서 다시). 받지 못한 조각은 다음 부름에서 다시 받는다(onceImport)
 */
export function chunkFailText(what: 'measure' | 'viewer', online: boolean): string {
  if (what === 'measure')
    return online
      ? '측정 도구를 받지 못했습니다. 앱의 새 버전이 나왔을 수 있습니다. 새로 고친 뒤 열어 둔 파일은 최근 문서에서 다시 여세요.'
      : '인터넷 연결이 끊겨 측정 도구를 받지 못했습니다. 연결되면 줄자·각도기 단추를 다시 누르세요.';
  return online
    ? '3D 보기 기능을 받지 못했습니다. 앱의 새 버전이 나왔을 수 있습니다. 새로 고친 뒤 파일을 다시 여세요.'
    : '인터넷 연결이 끊겨 3D 보기 기능을 받지 못했습니다. 연결되면 파일을 다시 여세요.';
}

/**
 * 처음 켤 때 조각을 받는 도구 켜기: 받는 동안 다시 부르면 바란 값만 바꾸고(받기는 한 번 — 단추를 여러 번 눌러도 꼬이지 않는다),
 * null이면 바람을 거둔다(같은 단추 다시 누르기·Esc). 받기가 끝나면 그때 바라던 값과 오류(없으면 null)를 done에 넘긴다.
 */
export class FirstUse<M> {
  private wantValue: M | null = null;
  private loadingValue = false;

  constructor(
    private readonly load: () => Promise<unknown>,
    private readonly done: (want: M | null, error: unknown) => void,
  ) {}

  /** 받는 중인지 */
  get loading(): boolean {
    return this.loadingValue;
  }

  /** 받는 동안 바라는 값(받는 중이 아니면 null) */
  get wanted(): M | null {
    return this.loadingValue ? this.wantValue : null;
  }

  /** 바라는 값을 정한다. 받는 중이 아니고 값이 있으면 받기 시작한다 */
  request(want: M | null): void {
    this.wantValue = want;
    if (want === null || this.loadingValue) return;
    this.loadingValue = true;
    this.load().then(
      () => this.finish(null),
      (e: unknown) => this.finish(e ?? new Error('load failed')),
    );
  }

  private finish(error: unknown): void {
    const want = this.wantValue;
    this.loadingValue = false;
    this.wantValue = null;
    this.done(want, error);
  }
}
